#include <iostream>
#include <vector>

using namespace std;

int s, k, p;
vector<bool> was1, was2;

void bfs() {
    vector<int> v;
    for (int i = 0; i < s; i++) {
        if (was1[i])
            v.push_back(i);
    }

    int q = 0;
    while (q < v.size()) {
        int x = v[q++];
        int y = x + p * k;
        if (y >= 0 && y <= s && !was1[y]) {
            was1[y] = 1;
            v.push_back(y);
        }
    }
}

void solve() {
    cin >> s >> k;
    if (s % k == 0) {
        cout << k << endl;
        return;
    }
    if (s > k * k) {
        cout << max(1, k - 2) << endl;
        return;
    }

    was1.resize(s + 1);
    was2.resize(s + 1);
    for (int i = 0; i <= s; i++) {
        was1[i] = was2[i] = 0;
    }

    p = 1;
    was1[k] = 1;
    while (1) {
        bfs();
        if (was1[s]) {
            cout << k << endl;
            return;
        }
        k = max(k - 1, 1);
        p *= -1;
        for (int i = 0; i <= s; i++) {
            was2[i] = 0;
        }
        for (int i = 0; i < s; i++) {
            if (was1[i]) {
                if (i + p * k >= 0 && i + p * k <= s) {
                    was2[i + p * k] = 1;
                }
            }
        }
        swap(was1, was2);
    }


}

int main() {
    int t;
    cin >> t;
    while (t--) {
        solve();
    }
}

